        /* Ad wrappers stretch to the full content column width. */
        .grc-ad-wrapper { width: 100%; }
        /* Collapse the wrapper when GPT has hidden the inner slot div.
           GPT sets display:none on the slot div itself; without this rule
           the wrapper block still occupies vertical space in the layout. */
        .grc-ad-wrapper:has(> div[style*="display: none"]),
        .grc-ad-wrapper:has(> div[style*="display:none"]) { display: none; }
        /* Bento homes: the top01 slot must take no space until GPT fills it. The
           stylesheet-wide .grc-ad-wrapper min-height (50px) plus the slot's inline
           20px margins reserved ~50px that collapsed when GAM returned no ad,
           shifting the whole bento up (the dominant CLS source). With a creative the
           slot grows to the creative height, and the gap below returns only then. */
        #grc-bento-nuevo .grc-ad-top01 .grc-ad-wrapper,
        #grc-bento-nuevo .grc-ad-top01 [id^="div-gpt-ad"] { margin: 0 !important; }
